// 1. 定义 5 个压缩率
const rates = [1.0, 0.8, 0.5, 0.3, 0.1];

// 2. 准备 FinQA (高风险) 数据（带真实背景）
const finqa_data = [
  { id: 1, q: "what is the net change in net revenue during 2015 for entergy corporation?", gt: "94", ctx: "Context: entergy corporation... Table Data: [['2014 net revenue', '$ 5735'], ['2015 net revenue', '$ 5829']]" },
  { id: 2, q: "what percentage of total facilities as measured in square feet are leased?", gt: "14.5", ctx: "Context: item 1b . unresolved staff comments... Table Data: [['owned facilities1', '30.7', '17.2', '47.9'], ['leased facilities2', '2.1', '6.0', '8.1'], ['total facilities', '32.8', '23.2', '56.0']]" },
  { id: 3, q: "what is the percentage change in cash flow hedges in 2011 compare to the 2010?", gt: "9.9", ctx: "Context: undesignated hedges was $ 41.2 million ... Table Data: [['other income', '$ -4614', '$ 4614', '$ 2014']]" },
  { id: 4, q: "what portion of total purchase price is related to stock awards?", gt: "2.9", ctx: "Context: metavante on october 1 , 2009 ... Table Data: [['value of metavante common stock', '$ 4066.4'], ['value of metavante stock awards', '121.4'], ['total purchase price', '$ 4187.8']]" },
  { id: 5, q: "what was the difference in percentage cumulative total shareholder return on masco common stock versus the s&p 500 index for the five year period ended 2017?", gt: "111.97", ctx: "Context: performance graph the table below compares ... Table Data: [['', '2013', '2017'], ['masco', '$ 138.48', '$ 318.46'], ['s&p 500 index', '$ 132.04', '$ 206.49']]" }
];

// 3. 准备 FAQ (低风险) 数据（带真实背景）
const faq_data = [
  { id: 1, q: "How do I request a refund for my order?", gt: "My Orders", ctx: "Refund Policy: We want you to be completely satisfied with your purchase. If you are not satisfied, you may request a refund within 30 days of the original purchase date. To request a refund, please go to the 'My Orders' section..." },
  { id: 2, q: "My package hasn't arrived yet, can you track it?", gt: "tracking number", ctx: "Shipping and Delivery: ... Once your order has shipped, you will receive a tracking number via email. You can use this tracking number to monitor the status of your package..." },
  { id: 3, q: "I forgot my password, how do I reset it?", gt: "Forgot Password", ctx: "Account and Password: If you have forgotten your password, click on the 'Forgot Password' link on the login page. Enter the email address associated with your account..." },
  { id: 4, q: "Can I change the shipping address after placing the order?", gt: "not mentioned", ctx: "Shipping and Delivery: ... If your package has not arrived within the estimated delivery time, please check with your local post office or contact our support team." },
  { id: 5, q: "What is your return policy for electronics?", gt: "original packaging", ctx: "Refund Policy: ... Please note that items must be in their original packaging and unused. Once we receive your return, it may take 5-7 business days..." }
];

const results = [];

// 4. 核心逻辑：双层循环生成所有组合，并完美拼接 Context 和 Question
for (const rate of rates) {

  // 组装 FinQA
  for (let i = 0; i < finqa_data.length; i++) {
    results.push({
      Dataset: "FinQA_HighRisk",
      Query_ID: finqa_data[i].id,
      // 核心：把背景和问题拼在一起！
      Question: finqa_data[i].ctx + "\n\nQuestion: " + finqa_data[i].q,
      Ground_Truth: finqa_data[i].gt,
      Rate: rate
    });
  }

  // 组装 FAQ
  for (let i = 0; i < faq_data.length; i++) {
    results.push({
      Dataset: "FAQ_LowRisk",
      Query_ID: faq_data[i].id,
      // 核心：把背景和问题拼在一起！
      Question: faq_data[i].ctx + "\n\nQuestion: " + faq_data[i].q,
      Ground_Truth: faq_data[i].gt,
      Rate: rate
    });
  }
}

return results;

function isAnswerCorrect(response, groundTruth) {
  if (response === undefined || response === null || groundTruth === undefined || groundTruth === null) {
    return false;
  }

  const rawResp = String(response);
  const rawGT = String(groundTruth);

  // 1. FAQ Q4 特殊容错机制
  if (rawGT.toLowerCase().includes("not mentioned")) {
    return rawResp.toLowerCase().includes("not mentioned");
  }

  // 2. 强大的正则清理
  const normalize = (s) =>
    String(s)
      .toLowerCase()
      .replace(/^\s*\d+[\.\)]\s+/gm, '') 
      .replace(/[^\p{L}\p{N}\s.\-]/gu, ' ') 
      .replace(/\s+/g, ' ')
      .trim();

  const cleanResp = normalize(rawResp);
  const cleanGT = normalize(rawGT);

  // 3. 增强的数值容差匹配 (FinQA)
  const gtPercentMatch = rawGT.trim().match(/^(-?\d+(?:\.\d+)?)\s*%$/);
  let gtNumber = null;

  if (gtPercentMatch) {
    gtNumber = parseFloat(gtPercentMatch[1]);
  } else if (/^-?\d+(\.\d+)?$/.test(cleanGT)) {
    gtNumber = parseFloat(cleanGT);
  }

  if (gtNumber !== null) {
    const respNumbers = cleanResp.match(/-?\d+(\.\d+)?/g) || [];
    for (const numStr of respNumbers) {
      const num = parseFloat(numStr);
      if (Math.abs(num - gtNumber) <= 0.5) return true;
      if (Math.abs(num * 100 - gtNumber) <= 0.5) return true;
      if (Math.abs(num / 100 - gtNumber) <= 0.5) return true;
    }
    return false;
  }

  // 4. 文本片段包含匹配 (FAQ兜底)
  if (!cleanGT) return false;
  return cleanResp.includes(cleanGT);
}

// ==========================================
// 主体执行逻辑
// ==========================================
const response = $json.response || "";
const originalData = $('Loop Over Items').item.json;
const groundTruth = String(originalData.Ground_Truth || "");

let finalResponse = response;
let finalModel = $json.model;
let fallbackTriggered = "No";
let finalIsCorrect = isAnswerCorrect(response, groundTruth);

let cheapPromptTokens = Number($json.prompt_eval_count || 0);
let cheapOutputTokens = Number($json.eval_count || 0);
let fallbackPromptTokens = 0;
let fallbackOutputTokens = 0;
let latency_seconds = Number($json.total_duration || 0) / 1e9;

if (!finalIsCorrect) {
  fallbackTriggered = "Yes";
  finalModel = "llama3:8b";

  try {
    const httpRequest = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://127.0.0.1:11434/api/generate',
      body: {
        model: "llama3:8b",
        prompt: "Based on the context: " + originalData.Question + " \n\n Answer: (If the answer is not in the context, output exactly 'Not mentioned in the context') ",
        stream: false
      },
      json: true
    });

    finalResponse = httpRequest.response || "Fallback Error";
    finalIsCorrect = isAnswerCorrect(finalResponse, groundTruth);

    fallbackPromptTokens = Number(httpRequest.prompt_eval_count || 0);
    fallbackOutputTokens = Number(httpRequest.eval_count || 0);
    latency_seconds += Number(httpRequest.total_duration || 0) / 1e9;
  } catch (error) {
    finalResponse = "Fallback Failed: " + error.message;
  }
}

// ==========================================
// 导出数据（已加上中括号返回数组）
// ==========================================
return [
  {
    Dataset: originalData.Dataset,
    Query_ID: originalData.Query_ID,
    Rate: originalData.Rate,
    Is_Correct: finalIsCorrect,
    Question: String(originalData.Question || "").replace(/[\r\n]+/g, " "),
    Ground_Truth: groundTruth.replace(/[\r\n]+/g, " "),
    Model_Response: String(finalResponse || "").replace(/[\r\n]+/g, " "),
    Model_Used: finalModel,
    Fallback_Triggered: fallbackTriggered,
    Cheap_Prompt_Tokens: cheapPromptTokens,
    Cheap_Output_Tokens: cheapOutputTokens,
    Fallback_Prompt_Tokens: fallbackPromptTokens,
    Fallback_Output_Tokens: fallbackOutputTokens,
    Prompt_Tokens: cheapPromptTokens + fallbackPromptTokens,
    Output_Tokens: cheapOutputTokens + fallbackOutputTokens,
    Total_Tokens: cheapPromptTokens + cheapOutputTokens + fallbackPromptTokens + fallbackOutputTokens,
    Latency_Seconds: latency_seconds
  }
];
